drills.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  02 · the exception handler goes first★★☆ core
//  concepts: try/catch around next · response started · registration order
// ─────────────────────────────────────────────────────────────────────────
//
//  The handler can only catch what runs INSIDE it: everything registered after it.

using static Bootcamp.Check;

Func<RequestDelegate, RequestDelegate> ExceptionHandler(List<string> log)
{
    return next => async ctx =>
    {
        try
        {
            await next(ctx);
        }
        catch (Exception ex)
        {
            log.Add("unhandled: " + ex.Message);
            if (ctx.HasStarted) throw;
            ctx.Headers.Clear();
            ctx.Headers["Cache-Control"] = "no-cache,no-store";
            ctx.Headers["Pragma"] = "no-cache";
            ctx.Headers["Expires"] = "-1";
            ctx.Status = 500;
            ctx.Problem = new Problem(500, "An error occurred while processing your request.", null);
        }
    };
}

Func<RequestDelegate, RequestDelegate> Throwing(string message) => next => ctx => throw new InvalidOperationException(message);

RequestDelegate Endpoint(int status) => ctx => { ctx.Status = status; return Task.CompletedTask; };

drills.tests:
// ──────────────────────────── tests ──────────────────────────────────────

Test("an endpoint exception becomes a 500 problem without its message", async () =>
{
    var log = new List<string>();
    var app = ExceptionHandler(log)(_ => throw new InvalidOperationException("connection string Server=db1;Password=hunter2"));
    var ctx = new Context("/orders");
    await app(ctx);
    Eq(ctx.Status, 500);
    Eq(ctx.Problem, new Problem(500, "An error occurred while processing your request.", null));
    Eq(log, new[] { "unhandled: connection string Server=db1;Password=hunter2" });
});

Test("headers set before the throw are cleared and caching is turned off", async () =>
{
    var app = ExceptionHandler(new List<string>())(ctx => { ctx.Headers["ETag"] = "\"v7\""; ctx.Headers["X-Order-Id"] = "42"; throw new InvalidOperationException("boom"); });
    var ctx = new Context("/orders/42");
    await app(ctx);
    Eq(ctx.Headers.OrderBy(h => h.Key).Select(h => h.Key + ": " + h.Value), new[] { "Cache-Control: no-cache,no-store", "Expires: -1", "Pragma: no-cache" });
});

Test("middleware registered before the handler is not covered (wrong order)", async () =>
{
    var log = new List<string>();
    var app = Throwing("rate limiter crashed")(ExceptionHandler(log)(Endpoint(200)));
    await ThrowsAsync<InvalidOperationException>(() => app(new Context("/orders")), "rate limiter crashed");
    Eq(log.Count, 0);
});

Test("a response that has started is not rewritten (boundary)", async () =>
{
    var log = new List<string>();
    var app = ExceptionHandler(log)(ctx => { ctx.Status = 200; ctx.HasStarted = true; throw new IOException("client went away mid-body"); });
    var ctx = new Context("/export.csv");
    await ThrowsAsync<IOException>(() => app(ctx), "mid-body");
    Eq((ctx.Status, ctx.Problem), (200, (Problem?)null));
    Eq(log, new[] { "unhandled: client went away mid-body" });
});

Test("a successful request passes through untouched", async () =>
{
    var log = new List<string>();
    var app = ExceptionHandler(log)(ctx => { ctx.Status = 201; ctx.Headers["Location"] = "/orders/7"; return Task.CompletedTask; });
    var ctx = new Context("/orders");
    await app(ctx);
    Eq((ctx.Status, ctx.Headers["Location"], ctx.Problem, log.Count), (201, "/orders/7", (Problem?)null, 0));
});

Test("a short-circuit 401 is an answer, not an error", async () =>
{
    Func<RequestDelegate, RequestDelegate> auth = next => ctx => { ctx.Status = 401; return Task.CompletedTask; };
    var app = ExceptionHandler(new List<string>())(auth(Endpoint(200)));
    var ctx = new Context("/admin");
    await app(ctx);
    Eq((ctx.Status, ctx.Problem), (401, (Problem?)null));
});

