// ─────────────────────────────────────────────────────────────────────────
//  03 · authorization after routing and authentication★★★ core
//  concepts: endpoint metadata · 401 vs 403 · middleware order
// ─────────────────────────────────────────────────────────────────────────
//
//  Authorization needs two things other middleware produce: the endpoint and the user.

using static Bootcamp.Check;

Func<RequestDelegate, RequestDelegate> Authorization()
{
    // TODO: no endpoint yet -> pass through; otherwise record that you ran, then 401 / 403 / next
    throw new NotImplementedException();
}

// ── the other middleware and the endpoint middleware (given) ──

Func<RequestDelegate, RequestDelegate> Routing(Dictionary<string, Endpoint> routes) =>
    next => ctx => { ctx.Endpoint = routes.GetValueOrDefault(ctx.Path); return next(ctx); };

Func<RequestDelegate, RequestDelegate> Authentication(Dictionary<string, User> tokens) =>
    next => ctx => { if (ctx.Token is not null && tokens.TryGetValue(ctx.Token, out var user)) ctx.User = user; return next(ctx); };

// what MapGet/MapControllers end in: refuses to run a protected endpoint that authorization never saw
Task Endpoints(Context ctx)
{
    if (ctx.Endpoint is null) { ctx.Status = 404; return Task.CompletedTask; }
    if (ctx.Endpoint.RequiresUser && !ctx.AuthorizationRan)
        throw new InvalidOperationException($"Endpoint {ctx.Endpoint.Name} contains authorization metadata, but a middleware was not found that supports authorization.");
    ctx.Log.Add("ran " + ctx.Endpoint.Name);
    return Task.CompletedTask;
}

var routes = new Dictionary<string, Endpoint>
{
    ["/orders"] = new("orders", RequiresUser: true),
    ["/admin/refunds"] = new("refunds", RequiresUser: true, Role: "admin"),
    ["/health"] = new("health"),
};
var tokens = new Dictionary<string, User> { ["t-ana"] = new("ana"), ["t-root"] = new("root", "admin") };

drills.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  03 · authorization after routing and authentication★★★ core
//  concepts: endpoint metadata · 401 vs 403 · middleware order
// ─────────────────────────────────────────────────────────────────────────
//
//  Authorization needs two things other middleware produce: the endpoint and the user.

using static Bootcamp.Check;

Func<RequestDelegate, RequestDelegate> Authorization()
{
    return next => ctx =>
    {
        var endpoint = ctx.Endpoint;
        if (endpoint is null) return next(ctx);
        ctx.AuthorizationRan = true;
        if (!endpoint.RequiresUser) return next(ctx);
        if (ctx.User is null)
        {
            ctx.Status = 401;
            return Task.CompletedTask;
        }
        if (endpoint.Role is not null && !ctx.User.Roles.Contains(endpoint.Role))
        {
            ctx.Status = 403;
            return Task.CompletedTask;
        }
        return next(ctx);
    };
}

// ── the other middleware and the endpoint middleware (given) ──

Func<RequestDelegate, RequestDelegate> Routing(Dictionary<string, Endpoint> routes) =>
    next => ctx => { ctx.Endpoint = routes.GetValueOrDefault(ctx.Path); return next(ctx); };

Func<RequestDelegate, RequestDelegate> Authentication(Dictionary<string, User> tokens) =>
    next => ctx => { if (ctx.Token is not null && tokens.TryGetValue(ctx.Token, out var user)) ctx.User = user; return next(ctx); };

// what MapGet/MapControllers end in: refuses to run a protected endpoint that authorization never saw
Task Endpoints(Context ctx)
{
    if (ctx.Endpoint is null) { ctx.Status = 404; return Task.CompletedTask; }
    if (ctx.Endpoint.RequiresUser && !ctx.AuthorizationRan)
        throw new InvalidOperationException($"Endpoint {ctx.Endpoint.Name} contains authorization metadata, but a middleware was not found that supports authorization.");
    ctx.Log.Add("ran " + ctx.Endpoint.Name);
    return Task.CompletedTask;
}

var routes = new Dictionary<string, Endpoint>
{
    ["/orders"] = new("orders", RequiresUser: true),
    ["/admin/refunds"] = new("refunds", RequiresUser: true, Role: "admin"),
    ["/health"] = new("health"),
};
var tokens = new Dictionary<string, User> { ["t-ana"] = new("ana"), ["t-root"] = new("root", "admin") };

drills.tests:
// ──────────────────────────── tests ──────────────────────────────────────

// the template order: routing, then authentication, then authorization, then the endpoint
RequestDelegate TemplateOrder() => Routing(routes)(Authentication(tokens)(Authorization()(Endpoints)));

Test("the template order lets a valid token reach the endpoint", async () =>
{
    var ctx = new Context("/orders", token: "t-ana");
    await TemplateOrder()(ctx);
    Eq((ctx.Status, ctx.Log.Count == 1 ? ctx.Log[0] : null), (200, "ran orders"));
});

Test("no user is 401; a user without the role is 403", async () =>
{
    var anonymous = new Context("/orders");
    var ana = new Context("/admin/refunds", token: "t-ana");
    var root = new Context("/admin/refunds", token: "t-root");
    var app = TemplateOrder();
    await app(anonymous);
    await app(ana);
    await app(root);
    Eq((anonymous.Status, ana.Status, root.Status), (401, 403, 200));
    Eq((anonymous.Log.Count, ana.Log.Count, root.Log.Count), (0, 0, 1));
});

Test("an anonymous endpoint needs no user", async () =>
{
    var ctx = new Context("/health");
    await TemplateOrder()(ctx);
    Eq((ctx.Status, ctx.Log.Count), (200, 1));
});

Test("authorization before routing sees no endpoint, so the endpoint refuses to run (wrong order)", async () =>
{
    var app = Authorization()(Routing(routes)(Authentication(tokens)(Endpoints)));
    var ctx = new Context("/orders", token: "t-ana");
    await ThrowsAsync<InvalidOperationException>(() => app(ctx), "authorization metadata");
    Eq(ctx.Log.Count, 0);
});

Test("authorization before authentication answers 401 to a valid token (wrong order)", async () =>
{
    var app = Routing(routes)(Authorization()(Authentication(tokens)(Endpoints)));
    var ctx = new Context("/orders", token: "t-ana");
    await app(ctx);
    Eq((ctx.Status, ctx.Log.Count), (401, 0));
});

Test("an unknown path is a 404 from the endpoint middleware, not a 401 (boundary)", async () =>
{
    var ctx = new Context("/nope");
    await TemplateOrder()(ctx);
    Eq(ctx.Status, 404);
});

