// ──────────────────────────── types ──────────────────────────────────────

delegate Task RequestDelegate(Context ctx);

/// <summary>a routed endpoint and its authorization metadata ([Authorize], [Authorize(Roles = ...)])</summary>
record Endpoint(string Name, bool RequiresUser = false, string? Role = null);

class User(string name, params string[] roles)
{
    public string Name { get; } = name;
    public string[] Roles { get; } = roles;
}

class Context(string path, string? token = null)
{
    public string Path { get; } = path;
    /// <summary>the bearer token the client sent (null = none)</summary>
    public string? Token { get; } = token;
    public int Status { get; set; } = 200;
    /// <summary>set by routing (HttpContext.GetEndpoint())</summary>
    public Endpoint? Endpoint { get; set; }
    /// <summary>set by authentication (HttpContext.User); null = anonymous</summary>
    public User? User { get; set; }
    /// <summary>the marker the real authorization middleware leaves for the endpoint middleware</summary>
    public bool AuthorizationRan { get; set; }
    public List<string> Log { get; } = new();
}

drills.explanation:
Pass through when there is no endpoint, leave the marker, then challenge or forbid:

```csharp
return next => ctx =>
{
    var endpoint = ctx.Endpoint;
    if (endpoint is null) return next(ctx);
    ctx.AuthorizationRan = true;
    if (!endpoint.RequiresUser) return next(ctx);
    if (ctx.User is null) { ctx.Status = 401; return Task.CompletedTask; }
    if (endpoint.Role is not null && !ctx.User.Roles.Contains(endpoint.Role)) { ctx.Status = 403; return Task.CompletedTask; }
    return next(ctx);
};
```

The tests catch three plausible wrong versions: one that answers 403 to an anonymous caller (the client should be challenged to log in, 401), one that denies whenever no endpoint is known (the boundary test expects the endpoint middleware's 404 for an unknown path), and one that sets the marker even without an endpoint, which would let the wrong-order pipeline run a protected endpoint with no check at all.
